mapper.select:
select pay.pay_type partType, pay.pay_cycle partCycle
    from FIN_CASH_PAY_RULE pay, FIN_CASH_INFO info
   where info.cash_id = pay.cash_id
     and info.CASH_TYPE_1 = #{cashType1,  jdbcType = VARCHAR}
     and info.CASH_TYPE_2 = #{cashType2,  jdbcType = VARCHAR}
     and info.FINPROD_ID = #{finprodId, jdbcType = VARCHAR}
     and pay.eff_date=(
     select max(pay2.eff_date)
     from FIN_CASH_PAY_RULE pay2 
     where pay2.cash_id=info.cash_id
       and DATE_FORMAT(pay2.eff_date, '%Y%m%d') <=
                   #{cdate,jdbcType=VARCHAR}                 
     )
